{
  "name": "RTDE实时数据交换客户端",
  "name_en": "RTDE Real-Time Data Exchange Client",
  "manufacturer": "",
  "description": "用于与控制器建立RTDE通信会话的非物理软件组件。它可连接或断开会话、协商协议版本、配置输入/输出数据流，并收发实时数据与消息，常用于实验自动化系统与控制器之间的数据交换、状态监测和集成通信。",
  "description_en": "A non-physical software component for establishing RTDE communication sessions with a controller. It can connect and disconnect, negotiate protocol versions, configure input/output data streams, and send or receive real-time data and messages. It is used in laboratory automation to integrate external software with a controller for data exchange and status monitoring.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到RTDE控制器会话。",
      "description_en": "Connect to an RTDE controller session."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开RTDE控制器会话。",
      "description_en": "Disconnect the RTDE controller session."
    },
    {
      "action_name": "auto-is_connected",
      "description": "检查是否已连接到RTDE会话。",
      "description_en": "Check whether the RTDE session is connected."
    },
    {
      "action_name": "auto-negotiate_protocol_version",
      "description": "协商RTDE协议版本。",
      "description_en": "Negotiate the RTDE protocol version."
    },
    {
      "action_name": "auto-send_input_setup",
      "description": "配置RTDE输入变量及其数据类型。",
      "description_en": "Configure RTDE input variables and their data types."
    },
    {
      "action_name": "auto-send_output_setup",
      "description": "配置RTDE输出变量、数据类型和更新频率。",
      "description_en": "Configure RTDE output variables, data types, and update frequency."
    },
    {
      "action_name": "auto-send_start",
      "description": "启动RTDE数据交换。",
      "description_en": "Start RTDE data exchange."
    },
    {
      "action_name": "auto-send_pause",
      "description": "暂停RTDE数据交换。",
      "description_en": "Pause RTDE data exchange."
    },
    {
      "action_name": "auto-send",
      "description": "发送RTDE输入数据包。",
      "description_en": "Send an RTDE input data package."
    },
    {
      "action_name": "auto-receive",
      "description": "接收RTDE输出数据包。",
      "description_en": "Receive an RTDE output data package."
    },
    {
      "action_name": "auto-send_message",
      "description": "发送RTDE文本消息。",
      "description_en": "Send an RTDE text message."
    },
    {
      "action_name": "auto-has_data",
      "description": "检查是否有可读取的RTDE数据。",
      "description_en": "Check whether RTDE data is available to read."
    },
    {
      "action_name": "auto-get_controller_version",
      "description": "获取控制器版本。",
      "description_en": "Get controller version."
    }
  ],
  "tag_hints": [
    "RTDE communication",
    "real-time data exchange",
    "controller session",
    "protocol negotiation",
    "robot controller integration",
    "streaming telemetry",
    "input/output recipe setup"
  ]
}

